use std :: collections :: { BTreeSet , HashMap } ; use std :: path :: { Path , PathBuf } ; use forge_domain :: { FileHash , FileStatus , SyncProgress , SyncStatus } ; use pretty_assertions :: assert_eq ; use super :: * ; impl WorkspaceStatus { # [doc = " Creates a sync plan from remote file hashes."] # [doc = ""] # [doc = " Paths in `remote_files` that are relative are joined with `base_dir` to"] # [doc = " produce absolute paths. Paths that are already absolute are kept as-is."] # [doc = ""] # [doc = " # Arguments"] # [doc = ""] # [doc = " * `base_dir` - The workspace root directory used to absolutize paths"] # [doc = " * `remote_files` - Vector of remote file hashes from the server"] pub fn new (base_dir : impl Into < PathBuf > , remote_files : Vec < FileHash >) -> Self { let base_dir = base_dir . into () ; let remote_files = remote_files . into_iter () . map (| f | FileHash { path : absolutize (& base_dir , & f . path) , hash : f . hash }) . collect () ; Self { base_dir , remote_files } } # [doc = " Derives file sync statuses by comparing local and remote files."] # [doc = ""] # [doc = " Both local and remote paths are expected to be absolute. Paths in"] # [doc = " `local_files` that are relative are joined with `base_dir` before"] # [doc = " comparison."] # [doc = ""] # [doc = " # Returns"] # [doc = ""] # [doc = " A sorted vector of `FileStatus` indicating the sync state of each file:"] # [doc = " - `InSync`: File exists in both local and remote with matching hashes"] # [doc = " - `Modified`: File exists in both but with different hashes"] # [doc = " - `New`: File exists only locally"] # [doc = " - `Deleted`: File exists only remotely"] pub fn file_statuses (& self , local_files : Vec < FileHash >) -> Vec < FileStatus > { let local_files : Vec < FileHash > = local_files . into_iter () . map (| f | FileHash { path : absolutize (& self . base_dir , & f . path) , hash : f . hash }) . collect () ; let local_hashes : HashMap < & str , & str > = local_files . iter () . map (| f | (f . path . as_str () , f . hash . as_str ())) . collect () ; let remote_hashes : HashMap < & str , & str > = self . remote_files . iter () . map (| f | (f . path . as_str () , f . hash . as_str ())) . collect () ; let mut all_paths : BTreeSet < & str > = BTreeSet :: new () ; all_paths . extend (local_hashes . keys () . copied ()) ; all_paths . extend (remote_hashes . keys () . copied ()) ; all_paths . into_iter () . filter_map (| path | { let local_hash = local_hashes . get (path) ; let remote_hash = remote_hashes . get (path) ; let status = match (local_hash , remote_hash) { (Some (l) , Some (r)) if l == r => SyncStatus :: InSync , (Some (_) , Some (_)) => SyncStatus :: Modified , (Some (_) , None) => SyncStatus :: New , (None , Some (_)) => SyncStatus :: Deleted , (None , None) => return None , } ; Some (FileStatus :: new (path . to_string () , status)) }) . collect () } # [doc = " Returns the sync operation paths based on local file hashes."] # [doc = ""] # [doc = " Unlike `get_operations`, this method only requires file hashes (not full"] # [doc = " content) and returns path lists suitable for driving a two-pass sync"] # [doc = " where content is read on-demand during upload."] pub fn get_sync_paths (& self , local_hashes : Vec < FileHash >) -> SyncPaths { let statuses = self . file_statuses (local_hashes) ; let mut delete = Vec :: new () ; let mut upload = Vec :: new () ; for status in statuses { match status . status { SyncStatus :: Modified | SyncStatus :: New => { upload . push (PathBuf :: from (status . path)) ; } SyncStatus :: Deleted => { delete . push (PathBuf :: from (status . path)) ; } SyncStatus :: InSync | SyncStatus :: Failed => { } } } SyncPaths { delete , upload } } }